mkdir -p ~/prep_tool && cd ~/prep_tool && git init -q -b main 2>/dev/null; cat > foodcost.py <<'EOF'
"""Restaurant food-cost calculator: recipes, ingredient prices, plate cost, prep list."""
from dataclasses import dataclass, field

@dataclass
class Ingredient:
    name: str
    unit_price: float   # dollars per unit
    unit: str = "lb"

@dataclass
class Recipe:
    name: str
    menu_price: float
    items: dict = field(default_factory=dict)  # ingredient name -> quantity in its unit

    def plate_cost(self, catalog):
        return sum(catalog[n].unit_price * q for n, q in self.items.items())

    def food_cost_pct(self, catalog):
        return 100 * self.plate_cost(catalog) / self.menu_price

def prep_list(recipes, covers):
    """recipes: list of (Recipe, expected_orders). Returns total ingredient quantities."""
    totals = {}
    for r, orders in recipes:
        for n, q in r.items.items():
            totals[n] = totals.get(n, 0) + q * orders
    return totals

def report(recipes, catalog):
    lines = []
    for r in recipes:
        lines.append(f"{r.name:<24} cost ${r.plate_cost(catalog):6.2f}  "
                     f"price ${r.menu_price:6.2f}  food cost {r.food_cost_pct(catalog):5.1f}%")
    return "\n".join(lines)

if __name__ == "__main__":
    catalog = {
        "chicken thigh": Ingredient("chicken thigh", 3.20),
        "rice": Ingredient("rice", 0.90),
        "tortilla": Ingredient("tortilla", 0.25, "ea"),
        "beans": Ingredient("beans", 1.40),
    }
    bowl = Recipe("Chicken rice bowl", 13.00, {"chicken thigh": 0.4, "rice": 0.3, "beans": 0.2})
    taco = Recipe("Chicken taco", 4.50, {"chicken thigh": 0.15, "tortilla": 2, "beans": 0.05})
    print(report([bowl, taco], catalog))
    print(prep_list([(bowl, 30), (taco, 50)], covers=80))
EOF
python3 foodcost.py && cat > test_foodcost.py <<'EOF'
from foodcost import Ingredient, Recipe, prep_list
def test_cost():
    c = {"a": Ingredient("a", 2.0)}
    r = Recipe("x", 10.0, {"a": 1.5})
    assert abs(r.plate_cost(c) - 3.0) < 1e-9
    assert abs(r.food_cost_pct(c) - 30.0) < 1e-9
def test_prep():
    r = Recipe("x", 10.0, {"a": 0.5})
    assert prep_list([(r, 4)], covers=0) == {"a": 2.0}
EOF
python3 -m pytest -q 2>/dev/null || python3 -m unittest -q test_foodcost 2>&1 | tail -2
printf "# prep_tool\nPrototype: recipe food-cost calculator and prep-list generator for small restaurants.\nRun: python3 foodcost.py\n" > README.md
git add -A && git commit -qm "Food-cost and prep-list prototype with tests" && git push -q http://gitea:3000/maya-exp01d-20261029-025455-017/prep_tool.git main 2>&1 | tail -2; echo done

